export function translate(language: Language, key: string) {
  const dictionary: Record<string, string> = { ...translations.en, ...extraTranslations.en, ...translations[language], ...extraTranslations[language] };
  return dictionary[key] ?? key;
}

export function roleLabel(role: string | undefined, language: Language) {
  if (role === 'ADMIN') return translate(language, 'Admin');
  if (role === 'PROAB') return translate(language, 'Prorab');
  return role ?? '';
}

